import{_ as n,C as o,o as r,c as s,a2 as t,b as l,w as a,a as d,E as p,a3 as c}from"./chunks/framework.CZqXuAiL.js";const y=JSON.parse('{"title":"Blue Server Properties Editor","description":"Modern server.properties configuration editor with 3-column grid layout and category filtering for Minecraft servers — a Blueprint extension for Pterodactyl Panel.","frontmatter":{"title":"Blue Server Properties Editor","description":"Modern server.properties configuration editor with 3-column grid layout and category filtering for Minecraft servers — a Blueprint extension for Pterodactyl Panel."},"headers":[],"relativePath":"blue-server-properties/index.md","filePath":"blue-server-properties/index.md","lastUpdated":1785522590000}'),g={name:"blue-server-properties/index.md"};function h(u,e,f,v,b,m){const i=o("Mermaid");return r(),s("div",null,[e[1]||(e[1]=t('<h1 id="blue-server-properties-editor" tabindex="-1">Blue Server Properties Editor <a class="header-anchor" href="#blue-server-properties-editor" aria-label="Permalink to &quot;Blue Server Properties Editor&quot;">​</a></h1><p><strong>A modern <code>server.properties</code> editor for Minecraft servers</strong> — a Blueprint extension for the Pterodactyl panel that gives your users a clean, categorized UI for their server&#39;s configuration instead of editing a raw text file.</p><p>Blue Server Properties Editor adds a <strong>Server Properties</strong> tab to every server&#39;s sidebar. It parses the live <code>server.properties</code> through Wings, renders every key with the right input — toggles for booleans, dropdowns for <code>difficulty</code> and <code>gamemode</code>, text for everything else — in a 3-column grid with category filtering, and writes changes back atomically.</p><div class="tip custom-block" style="margin-top:1.5rem;"><p><strong>Built for ALTIS TECH SOLUTIONS by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer">AnAverageBeing</a></strong><a href="https://github.com/AnAverageBeing/blue-server-properties" target="_blank" rel="noreferrer">GitHub Repo</a> · <a href="https://xdp.network" target="_blank" rel="noreferrer">Studio</a></p></div><div class="warning custom-block"><p class="custom-block-title">Minecraft servers only</p><p>The editor only works on servers in the Minecraft nest (nest ID <code>1</code>) — enforced by the backend and noted on the admin page.</p></div><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>',7)),(r(),l(c,null,{default:a(()=>[p(i,{id:"mermaid-23",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20Panel%5BPterodactyl%20Panel%5D%0A%20%20%20%20%20%20%20%20UI%5BServer%20Sidebar%20-%20Server%20Properties%20tab%5D%20--%3E%20API%5BClient%20API%20%2Fapi%2Fclient%2Fextensions%2Fblueserverproperties%5D%0A%20%20%20%20%20%20%20%20NAV%5BNavButtonUpdater%5D%20--%3E%7Crelabels%20tab%7C%20UI%0A%20%20%20%20%20%20%20%20ADMIN%5BAdmin%20Settings%20Page%5D%20--%3E%20JSON%5Bstorage%2Fapp%2Fblueserverproperties_config.json%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%20JSON%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Node%5BWings%20Node%5D%0A%20%20%20%20%20%20%20%20API%20--%3E%7CgetContent%20%2F%20putContent%7C%20WINGS%5BWings%20Daemon%5D%0A%20%20%20%20%20%20%20%20WINGS%20--%3E%20PROPS%5Bserver.properties%5D%0A%20%20%20%20end%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<p>The <strong>panel</strong> reads and writes <code>server.properties</code> through the Wings file API (nothing is cached — every open fetches the live file). The optional custom tab label lives in a small JSON config written from the admin page; <code>NavButtonUpdater</code> components apply it live across the server area.</p><p>A genuinely <strong>Blueprint-free</strong> variant of backend + frontend also ships inside the extension (<code>data/PanelFiles/</code>) for panels without Blueprint — see <a href="./getting-started/installation#blueprint-free-install-no-blueprint-at-all">Installation</a>.</p><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Structured editor</strong> — every <code>server.properties</code> key rendered with the right control: toggle for <code>true/false</code>, dropdowns for <code>difficulty</code> and <code>gamemode</code>, text inputs elsewhere.</li><li><strong>3-column grid + category filtering</strong> — find keys fast instead of scrolling a raw file.</li><li><strong>Live read/write through Wings</strong> — <code>getContent</code>/<code>putContent</code> on <code>server.properties</code>; comments and unknown keys are preserved untouched on save.</li><li><strong>Customizable sidebar label</strong> — rename the tab (default <code>Server Properties</code>, max 30 chars) from <strong>Admin → Extensions → Blue Server Properties Editor</strong>.</li><li><strong>Permission-aware</strong> — viewing requires <code>file.read</code>, saving requires <code>file.update</code> (Blueprint-free variant).</li><li><strong>Minecraft-only guard</strong> — the backend rejects non-Minecraft nests (the admin page explains the limitation).</li><li><strong>Two distributions</strong> — Blueprint package, manual standalone path, <strong>and</strong> a Blueprint-free PanelFiles variant.</li></ul><hr><h2 id="quick-install" tabindex="-1">Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueserverproperties-v1.12.4.blueprint</span></span></code></pre></div><p>See <a href="./getting-started/installation">Installation</a> for all three install paths, and the <a href="./configuration/reference">Configuration Reference</a> for every setting.</p>`,9))])}const P=n(g,[["render",h]]);export{y as __pageData,P as default};
